DROP TRIGGER IF EXISTS `activity_log_no_delete`;
DELIMITER $$
CREATE TRIGGER `activity_log_no_delete` BEFORE DELETE ON `activity_log` FOR EACH ROW SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'سجل الحركة لا يُحذف من أي دور، بما فيهم مدير النظام.'
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `activity_log_no_update`;
DELIMITER $$
CREATE TRIGGER `activity_log_no_update` BEFORE UPDATE ON `activity_log` FOR EACH ROW SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'سجل الحركة للإضافة فقط: لا يُعدَّل من أي دور. التصحيح بقيد عكسي معلّل.'
$$
DELIMITER ;

