--
-- Table structure for table `allocations`
--

DROP TABLE IF EXISTS `allocations`;
CREATE TABLE IF NOT EXISTS `allocations` (
  `allocation_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `receipt_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contract_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `currency` enum('ILS','USD','JOD','EUR') COLLATE utf8mb4_unicode_ci NOT NULL,
  `due_month` date NOT NULL,
  `allocated_by` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`allocation_id`),
  UNIQUE KEY `allocations_no_double_booking` (`receipt_code`,`contract_code`,`due_month`),
  KEY `allocations_allocated_by_foreign` (`allocated_by`),
  KEY `allocations_receipt_code_index` (`receipt_code`),
  KEY `allocations_contract_code_index` (`contract_code`),
  KEY `allocations_due_month_index` (`due_month`)
) ;

--
-- Triggers `allocations`
--
DROP TRIGGER IF EXISTS `allocations_within_payment_ins`;
DELIMITER $$
CREATE TRIGGER `allocations_within_payment_ins` BEFORE INSERT ON `allocations` FOR EACH ROW BEGIN 
            DECLARE receipt_cur  VARCHAR(10);
            DECLARE receipt_net  DECIMAL(12,2);
            DECLARE already_used DECIMAL(12,2);
            DECLARE msg VARCHAR(255);

            SELECT currency_original, net_received
              INTO receipt_cur, receipt_net
              FROM payments_in
             WHERE receipt_code = NEW.receipt_code;

            IF NEW.currency <> receipt_cur THEN
              SET msg = CONCAT('عملة التخصيص «', NEW.currency, '» تخالف عملة الإيصال «', receipt_cur,
                               '». لا يُطرح مبلغ من مبلغ بعملة أخرى.');
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
            END IF;

            SELECT COALESCE(SUM(amount), 0) INTO already_used
              FROM allocations
             WHERE receipt_code = NEW.receipt_code
               ;

            IF already_used + NEW.amount > receipt_net + 0.001 THEN
              SET msg = CONCAT('التخصيص يتجاوز الدفعة ', NEW.receipt_code,
                               '. المستلم صافياً: ', receipt_net,
                               '، المخصَّص سابقاً: ', already_used,
                               '، المطلوب إضافته: ', NEW.amount, '.');
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
            END IF;
         END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `allocations_within_payment_upd`;
DELIMITER $$
CREATE TRIGGER `allocations_within_payment_upd` BEFORE UPDATE ON `allocations` FOR EACH ROW BEGIN 
            DECLARE receipt_cur  VARCHAR(10);
            DECLARE receipt_net  DECIMAL(12,2);
            DECLARE already_used DECIMAL(12,2);
            DECLARE msg VARCHAR(255);

            SELECT currency_original, net_received
              INTO receipt_cur, receipt_net
              FROM payments_in
             WHERE receipt_code = NEW.receipt_code;

            IF NEW.currency <> receipt_cur THEN
              SET msg = CONCAT('عملة التخصيص «', NEW.currency, '» تخالف عملة الإيصال «', receipt_cur,
                               '». لا يُطرح مبلغ من مبلغ بعملة أخرى.');
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
            END IF;

            SELECT COALESCE(SUM(amount), 0) INTO already_used
              FROM allocations
             WHERE receipt_code = NEW.receipt_code
               AND allocation_id <> NEW.allocation_id;

            IF already_used + NEW.amount > receipt_net + 0.001 THEN
              SET msg = CONCAT('التخصيص يتجاوز الدفعة ', NEW.receipt_code,
                               '. المستلم صافياً: ', receipt_net,
                               '، المخصَّص سابقاً: ', already_used,
                               '، المطلوب إضافته: ', NEW.amount, '.');
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
            END IF;
         END
$$
DELIMITER ;

