  `recipient_relation` enum('الأم','الجد','الجدة','العم','العمة','الخال','الخالة','الأخ الأكبر','الأخت الكبرى','وصي معيّن قضائياً','جهة رعاية') COLLATE utf8mb4_unicode_ci NOT NULL,
  `method` enum('نقد مباشر','محفظة إلكترونية','تحويل بنكي','قسيمة شرائية','مساعدة عينية','دفع مباشر لجهة') COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_no` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `in_kind_valuation` decimal(12,2) DEFAULT NULL,
