  `health_status` text COLLATE utf8mb4_unicode_ci,
  `special_needs` tinyint(1) NOT NULL DEFAULT '0',
  `file_state` enum('مُقدَّم','قيد الفرز','بانتظار التوثيق','بانتظار الزيارة','قيد المراجعة النهائية','معتمد','مرفوض','موقوف مؤقتاً','مُنهى') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'مُقدَّم',
  `intake_date` date NOT NULL,
