  `end_reason` text COLLATE utf8mb4_unicode_ci,
  `reason_public` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason_public_by` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
