--
-- Triggers `orphans`
--
DROP TRIGGER IF EXISTS `orphans_documentation_guard`;
DELIMITER $$
CREATE TRIGGER `orphans_documentation_guard` BEFORE UPDATE ON `orphans` FOR EACH ROW BEGIN
              DECLARE doc_points   INT DEFAULT 0;
              DECLARE visit_points INT DEFAULT 0;
              DECLARE total_points INT DEFAULT 0;
              DECLARE msg VARCHAR(255);

              IF NEW.file_state = 'معتمد' AND OLD.file_state <> 'معتمد' THEN

                SELECT COALESCE(SUM(weight_points), 0) INTO doc_points
                  FROM documents
                 WHERE orphan_code = NEW.orphan_code
                    OR (family_code = NEW.family_code AND orphan_code IS NULL);

                -- الزيارة المراجَعة تُحتسب ما لم يكن تقريرها مرفوعاً كمستند أصلاً
                IF EXISTS (SELECT 1 FROM field_visits
                            WHERE family_code = NEW.family_code AND reviewed_at IS NOT NULL)
                   AND NOT EXISTS (SELECT 1 FROM documents
                            WHERE doc_type = 'تقرير زيارة'
                              AND (orphan_code = NEW.orphan_code
                                   OR (family_code = NEW.family_code AND orphan_code IS NULL)))
                THEN
                  SET visit_points = 25;
                END IF;

                SET total_points = LEAST(doc_points + visit_points, 100);

                IF total_points < 25 THEN
                  SET msg = CONCAT('لا يُعتمد الملف ', NEW.orphan_code,
                                   ' بدرجة توثيق ', total_points,
                                   ' — الحد الأدنى 25 نقطة (برونزي).');
                  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                END IF;

                SET NEW.doc_score = total_points;
              END IF;
            END
$$
DELIMITER ;

