  `coverage_pct` tinyint UNSIGNED NOT NULL DEFAULT '100',
  `money_type` enum('صدقة عامة','زكاة مال','زكاة فطر','كفارة','فدية','وقف','تبرع طوارئ') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'صدقة عامة',
  `start_date` date NOT NULL,
