  `end_date` date DEFAULT NULL,
  `state` enum('مسودة','نشط','متأخر','معرّض للانقطاع','منقطع','منتهٍ','مُلغى') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'مسودة',
