  KEY `sponsorships_channel_code_foreign` (`channel_code`)
) ;

--
-- Triggers `sponsorships`
--
DROP TRIGGER IF EXISTS `sponsorships_coverage_guard_ins`;
DELIMITER $$
CREATE TRIGGER `sponsorships_coverage_guard_ins` BEFORE INSERT ON `sponsorships` FOR EACH ROW BEGIN 
            DECLARE existing_total INT;
            DECLARE msg VARCHAR(255);
            IF NEW.state IN ('نشط','متأخر','معرّض للانقطاع','مسودة') THEN
              SELECT COALESCE(SUM(coverage_pct),0) INTO existing_total
                FROM sponsorships
               WHERE orphan_code = NEW.orphan_code
                 AND state IN ('نشط','متأخر','معرّض للانقطاع','مسودة')
                 AND contract_code <> NEW.contract_code;
              IF existing_total + NEW.coverage_pct > 100 THEN
                SET msg = CONCAT('مجموع نسب التغطية للطفل ', NEW.orphan_code,
                                 ' سيصبح ', existing_total + NEW.coverage_pct,
                                 '٪ وهو يتجاوز 100٪. القائم: ', existing_total,
                                 '٪، المضاف: ', NEW.coverage_pct, '٪.');
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
              END IF;
            END IF;
         END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `sponsorships_coverage_guard_upd`;
DELIMITER $$
CREATE TRIGGER `sponsorships_coverage_guard_upd` BEFORE UPDATE ON `sponsorships` FOR EACH ROW BEGIN 
            DECLARE existing_total INT;
            DECLARE msg VARCHAR(255);
            IF NEW.state IN ('نشط','متأخر','معرّض للانقطاع','مسودة') THEN
              SELECT COALESCE(SUM(coverage_pct),0) INTO existing_total
                FROM sponsorships
               WHERE orphan_code = NEW.orphan_code
                 AND state IN ('نشط','متأخر','معرّض للانقطاع','مسودة')
                 AND contract_code <> NEW.contract_code;
              IF existing_total + NEW.coverage_pct > 100 THEN
                SET msg = CONCAT('مجموع نسب التغطية للطفل ', NEW.orphan_code,
                                 ' سيصبح ', existing_total + NEW.coverage_pct,
                                 '٪ وهو يتجاوز 100٪. القائم: ', existing_total,
                                 '٪، المضاف: ', NEW.coverage_pct, '٪.');
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
              END IF;
            END IF;
         END
$$
DELIMITER ;

