--
-- Structure for view `v_commitment_vs_collected`
--
DROP TABLE IF EXISTS `v_commitment_vs_collected`;

DROP VIEW IF EXISTS `v_commitment_vs_collected`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_commitment_vs_collected`  AS SELECT `cur`.`currency` AS `currency`, coalesce(`c`.`monthly_commitment`,0) AS `monthly_commitment`, coalesce(`k`.`collected`,0) AS `collected`, (coalesce(`k`.`collected`,0) - coalesce(`c`.`monthly_commitment`,0)) AS `gap` FROM (((select `sponsorships`.`currency` AS `currency` from `sponsorships` union select `payments_in`.`currency_original` AS `currency_original` from `payments_in`) `cur` left join (select `sponsorships`.`currency` AS `currency`,sum(((`sponsorships`.`amount` * `sponsorships`.`coverage_pct`) / 100.0)) AS `monthly_commitment` from `sponsorships` where ((`sponsorships`.`state` in ('نشط','متأخر','معرّض للانقطاع')) and (`sponsorships`.`frequency` = 'شهري')) group by `sponsorships`.`currency`) `c` on((`c`.`currency` = `cur`.`currency`))) left join (select `payments_in`.`currency_original` AS `currency`,sum(`payments_in`.`net_received`) AS `collected` from `payments_in` where (date_format(`payments_in`.`received_at`,'%Y-%m') = date_format(curdate(),'%Y-%m')) group by `payments_in`.`currency_original`) `k` on((`k`.`currency` = `cur`.`currency`)))  ;

-- --------------------------------------------------------

--
-- Structure for view `v_data_quality`
--
DROP TABLE IF EXISTS `v_data_quality`;

DROP VIEW IF EXISTS `v_data_quality`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_data_quality`  AS SELECT 'سجلات منتهية الصلاحية' AS `issue`, count(0) AS `affected`, 'orphans' AS `src` FROM `orphans` WHERE ((`orphans`.`data_valid_until` < curdate()) AND (`orphans`.`file_state` = 'معتمد')) union all select 'أطفال تجاوزوا سن التخريج' AS `أطفال تجاوزوا سن التخريج`,count(0) AS `COUNT(*)`,'orphans' AS `orphans` from `orphans` where ((`orphans`.`file_state` = 'معتمد') and (`orphans`.`birth_date` <= (curdate() - interval coalesce((select cast(`s`.`value` as unsigned) from `settings` `s` where (`s`.`key` = 'max_continue_age')),18) year))) union all select 'تسليمات بلا تأكيد تجاوزت المهلة' AS `تسليمات بلا تأكيد تجاوزت المهلة`,count(0) AS `COUNT(*)`,'deliveries' AS `deliveries` from `v_unconfirmed_deliveries` where (`v_unconfirmed_deliveries`.`status` = 'معلّق للتحقيق') union all select 'وصي يستلم لأكثر من 5 أطفال' AS `وصي يستلم لأكثر من 5 أطفال`,count(0) AS `COUNT(*)`,'guardians' AS `guardians` from (select `g`.`guardian_code` AS `guardian_code` from (`guardians` `g` join `orphans` `o` on((`o`.`family_code` = `g`.`family_code`))) where (`g`.`is_recipient` = 1) group by `g`.`guardian_code` having (count(0) > 5)) `q` union all select 'نفس رقم الجوال على أكثر من 3 أسر' AS `نفس رقم الجوال على أكثر من 3 أسر`,count(0) AS `COUNT(*)`,'guardians' AS `guardians` from (select `guardians`.`phone_primary` AS `phone_primary` from `guardians` group by `guardians`.`phone_primary` having (count(distinct `guardians`.`family_code`) > 3)) `q2` union all select 'ملفات معتمدة بلا زيارة ميدانية' AS `ملفات معتمدة بلا زيارة ميدانية`,count(0) AS `COUNT(*)`,'orphans' AS `orphans` from (select `o`.`orphan_code` AS `orphan_code` from (`orphans` `o` left join `field_visits` `v` on((`v`.`family_code` = `o`.`family_code`))) where (`o`.`file_state` = 'معتمد') group by `o`.`orphan_code` having (count(`v`.`visit_code`) = 0)) `q3` union all select 'دفعات محصَّلة غير مخصصة' AS `دفعات محصَّلة غير مخصصة`,count(0) AS `COUNT(*)`,'payments_in' AS `payments_in` from `v_unallocated_payments` where (`v_unallocated_payments`.`remaining` > 0) union all select 'دفعات مخصَّصة بأكثر من المستلم' AS `دفعات مخصَّصة بأكثر من المستلم`,count(0) AS `COUNT(*)`,'payments_in' AS `payments_in` from `v_unallocated_payments` where (`v_unallocated_payments`.`remaining` < 0) union all select 'عملات بلا سعر صرف مثبَّت هذا الشهر' AS `عملات بلا سعر صرف مثبَّت هذا الشهر`,count(0) AS `COUNT(*)`,'fx_rates' AS `fx_rates` from (select `cur`.`currency` AS `currency` from (select `sponsorships`.`currency` AS `currency` from `sponsorships` union select `payments_in`.`currency_original` AS `currency_original` from `payments_in`) `cur` where ((`cur`.`currency` <> 'USD') and exists(select 1 from `fx_rates` `f` where ((`f`.`quote` = `cur`.`currency`) and (`f`.`base` = 'USD') and (`f`.`is_provisional` = 0) and (`f`.`month` = date_format(curdate(),'%Y-%m-01')))) is false)) `q4`  ;

