--
-- Structure for view `v_family_coverage`
--
DROP TABLE IF EXISTS `v_family_coverage`;

DROP VIEW IF EXISTS `v_family_coverage`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_family_coverage`  AS SELECT `f`.`family_code` AS `family_code`, `f`.`mother_name` AS `mother_name`, `f`.`governorate` AS `governorate`, count(distinct `o`.`orphan_code`) AS `orphans_total`, count(distinct (case when (`s`.`state` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`orphan_code` end)) AS `orphans_sponsored`, (count(distinct `o`.`orphan_code`) - count(distinct (case when (`s`.`state` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`orphan_code` end))) AS `orphans_waiting` FROM ((`families` `f` left join `orphans` `o` on(((`o`.`family_code` = `f`.`family_code`) and (`o`.`file_state` = 'معتمد')))) left join `sponsorships` `s` on((`s`.`orphan_code` = `o`.`orphan_code`))) GROUP BY `f`.`family_code`, `f`.`mother_name`, `f`.`governorate``governorate`  ;

-- --------------------------------------------------------

--
-- Structure for view `v_orphan_sponsorship`
--
DROP TABLE IF EXISTS `v_orphan_sponsorship`;

DROP VIEW IF EXISTS `v_orphan_sponsorship`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_orphan_sponsorship`  AS SELECT `o`.`orphan_code` AS `orphan_code`, `o`.`full_name` AS `full_name`, `o`.`family_code` AS `family_code`, `o`.`file_state` AS `file_state`, `o`.`need_score` AS `need_score`, `o`.`doc_score` AS `doc_score`, coalesce(sum((case when (`s`.`state` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`coverage_pct` else 0 end)),0) AS `covered_pct`, (case when (`o`.`file_state` in ('مُنهى','مرفوض')) then 'خارج البرنامج' when (`o`.`file_state` = 'موقوف مؤقتاً') then 'موقوف' when (`o`.`file_state` <> 'معتمد') then 'قيد المعالجة' when (coalesce(sum((case when (`s`.`state` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`coverage_pct` else 0 end)),0) >= 100) then 'مكفول' when (coalesce(sum((case when (`s`.`state` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`coverage_pct` else 0 end)),0) > 0) then 'مكفول جزئياً' else 'بانتظار كافل' end) AS `sponsorship_state` FROM (`orphans` `o` left join `sponsorships` `s` on((`s`.`orphan_code` = `o`.`orphan_code`))) GROUP BY `o`.`orphan_code`, `o`.`full_name`, `o`.`family_code`, `o`.`file_state`, `o`.`need_score`, `o`.`doc_score``doc_score`  ;

-- --------------------------------------------------------

--
-- Structure for view `v_unallocated_payments`
--
DROP TABLE IF EXISTS `v_unallocated_payments`;

DROP VIEW IF EXISTS `v_unallocated_payments`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_unallocated_payments`  AS SELECT `p`.`receipt_code` AS `receipt_code`, `p`.`sponsor_code` AS `sponsor_code`, `p`.`net_received` AS `net_received`, `p`.`currency_original` AS `currency_original`, `p`.`received_at` AS `received_at`, (to_days(curdate()) - to_days(`p`.`received_at`)) AS `days_unallocated`, (`p`.`net_received` - coalesce(sum(`a`.`amount`),0)) AS `remaining`, (case when ((`p`.`net_received` - coalesce(sum(`a`.`amount`),0)) < 0) then 'مخصَّص بأكثر من المستلم' else 'بانتظار التخصيص' end) AS `status` FROM (`payments_in` `p` left join `allocations` `a` on((`a`.`receipt_code` = `p`.`receipt_code`))) GROUP BY `p`.`receipt_code`, `p`.`sponsor_code`, `p`.`net_received`, `p`.`currency_original`, `p`.`received_at` HAVING (`remaining` <> 0)  ;

-- --------------------------------------------------------

--
-- Structure for view `v_unconfirmed_deliveries`
--
DROP TABLE IF EXISTS `v_unconfirmed_deliveries`;

DROP VIEW IF EXISTS `v_unconfirmed_deliveries`;
