--
-- Triggers `deliveries`
--
DROP TRIGGER IF EXISTS `deliveries_closed_month_guard`;
DELIMITER $$
CREATE TRIGGER `deliveries_closed_month_guard` BEFORE UPDATE ON `deliveries` FOR EACH ROW BEGIN
              DECLARE closed INT;
              SELECT COUNT(*) INTO closed FROM month_closings
               WHERE month = DATE_FORMAT(OLD.delivered_at, '%Y-%m-01');
              IF closed > 0 AND (NEW.amount_delivered <> OLD.amount_delivered
                                 OR NEW.amount_due <> OLD.amount_due
                                 OR NEW.commission_actual <> OLD.commission_actual) THEN
                SIGNAL SQLSTATE '45000'
                  SET MESSAGE_TEXT = 'الشهر مُقفل: لا يُعدَّل أي مبلغ فيه. التصحيح بقيد في الشهر التالي يشير للأصلي.';
              END IF;
            END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `deliveries_confirm_proof_insert`;
DELIMITER $$
CREATE TRIGGER `deliveries_confirm_proof_insert` BEFORE INSERT ON `deliveries` FOR EACH ROW BEGIN
                      IF (SELECT value FROM lookup_values WHERE id = NEW.proof_id) = 'تسجيل الموظف فقط' AND NEW.confirmed_at IS NOT NULL THEN
                        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'التسليم المؤكَّد لا يكون إثباته تسجيل الموظف وحده.';
                      END IF;
                    END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `deliveries_confirm_proof_update`;
DELIMITER $$
CREATE TRIGGER `deliveries_confirm_proof_update` BEFORE UPDATE ON `deliveries` FOR EACH ROW BEGIN
                      IF (SELECT value FROM lookup_values WHERE id = NEW.proof_id) = 'تسجيل الموظف فقط' AND NEW.confirmed_at IS NOT NULL THEN
                        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'التسليم المؤكَّد لا يكون إثباته تسجيل الموظف وحده.';
                      END IF;
                    END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `deliveries_currency_matches_order`;
DELIMITER $$
CREATE TRIGGER `deliveries_currency_matches_order` BEFORE INSERT ON `deliveries` FOR EACH ROW BEGIN
              DECLARE order_cur BIGINT UNSIGNED;
              DECLARE msg VARCHAR(255);

              SELECT currency_id INTO order_cur FROM disbursement_orders
               WHERE order_code = NEW.order_code;

              IF NEW.currency_id <> order_cur THEN
                SET msg = CONCAT('عملة التسليم «',
                  (SELECT value FROM lookup_values WHERE id = NEW.currency_id),
                  '» تخالف عملة أمر الصرف «',
                  (SELECT value FROM lookup_values WHERE id = order_cur), '».');
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
              END IF;
            END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `deliveries_require_approved_order`;
DELIMITER $$
CREATE TRIGGER `deliveries_require_approved_order` BEFORE INSERT ON `deliveries` FOR EACH ROW BEGIN
              DECLARE st VARCHAR(40);
              DECLARE msg VARCHAR(255);

              SELECT lv.value INTO st FROM disbursement_orders o
                JOIN lookup_values lv ON lv.id = o.state_id
               WHERE o.order_code = NEW.order_code;

              IF st NOT IN ('معتمد','منفَّذ') THEN
                SET msg = CONCAT('لا يُسجَّل تسليم على أمر صرف حالته «', COALESCE(st,'غير موجود'),
                  '». يلزم اعتماد الأمر أولاً.');
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
              END IF;
            END
$$
DELIMITER ;

