--
-- Triggers `orphans`
--
DROP TRIGGER IF EXISTS `orphans_documentation_guard`;
DELIMITER $$
CREATE TRIGGER `orphans_documentation_guard` BEFORE UPDATE ON `orphans` FOR EACH ROW BEGIN
              DECLARE doc_points   INT DEFAULT 0;
              DECLARE visit_points INT DEFAULT 0;
              DECLARE total_points INT DEFAULT 0;
              DECLARE approved_id  BIGINT UNSIGNED;
              DECLARE msg VARCHAR(255);

              SELECT id INTO approved_id FROM lookup_values
               WHERE list_key = 'FILE_STATES' AND value = 'معتمد' LIMIT 1;

              IF NEW.file_state_id = approved_id AND OLD.file_state_id <> approved_id THEN
                SELECT COALESCE(SUM(weight_points), 0) INTO doc_points
                  FROM documents
                 WHERE orphan_id = NEW.id
                    OR (family_code = NEW.family_code AND orphan_id IS NULL);

                IF EXISTS (SELECT 1 FROM field_visits
                            WHERE family_code = NEW.family_code AND reviewed_at IS NOT NULL)
                   AND NOT EXISTS (SELECT 1 FROM documents d
                            JOIN lookup_values lv ON lv.id = d.doc_type_id
                           WHERE lv.value = 'تقرير زيارة'
                             AND (d.orphan_id = NEW.id
                              OR (d.family_code = NEW.family_code AND d.orphan_id IS NULL)))
                THEN
                  SET visit_points = 25;
                END IF;

                SET total_points = LEAST(doc_points + visit_points, 100);

                IF total_points < 25 THEN
                  SET msg = CONCAT('لا يُعتمد الملف ', NEW.orphan_code,
                    ' بدرجة توثيق ', total_points, ' — الحد الأدنى 25 نقطة (برونزي).');
                  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                END IF;

                SET NEW.doc_score = total_points;
              END IF;
            END
$$
DELIMITER ;
