--
-- Structure for view `v_commitment_vs_collected`
--
DROP TABLE IF EXISTS `v_commitment_vs_collected`;

DROP VIEW IF EXISTS `v_commitment_vs_collected`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_commitment_vs_collected`  AS SELECT `cur`.`currency` AS `currency`, coalesce(`c`.`monthly_commitment`,0) AS `monthly_commitment`, coalesce(`k`.`collected`,0) AS `collected`, (coalesce(`k`.`collected`,0) - coalesce(`c`.`monthly_commitment`,0)) AS `gap` FROM (((select `lv`.`value` AS `currency` from (`sponsorships` `s` join `lookup_values` `lv` on((`lv`.`id` = `s`.`currency_id`))) union select `lv`.`value` AS `value` from (`payments_in` `p` join `lookup_values` `lv` on((`lv`.`id` = `p`.`currency_original_id`)))) `cur` left join (select `lvc`.`value` AS `currency`,sum(((`s`.`amount` * `s`.`coverage_pct`) / 100.0)) AS `monthly_commitment` from (((`sponsorships` `s` join `lookup_values` `lvc` on((`lvc`.`id` = `s`.`currency_id`))) join `lookup_values` `lvs` on((`lvs`.`id` = `s`.`state_id`))) join `lookup_values` `lvf` on((`lvf`.`id` = `s`.`frequency_id`))) where ((`lvs`.`value` in ('نشط','متأخر','معرّض للانقطاع')) and (`lvf`.`value` = 'شهري')) group by `lvc`.`value`) `c` on((`c`.`currency` = `cur`.`currency`))) left join (select `lvc`.`value` AS `currency`,sum(`p`.`net_received`) AS `collected` from (`payments_in` `p` join `lookup_values` `lvc` on((`lvc`.`id` = `p`.`currency_original_id`))) where (date_format(`p`.`received_at`,'%Y-%m') = date_format(curdate(),'%Y-%m')) group by `lvc`.`value`) `k` on((`k`.`currency` = `cur`.`currency`)))  ;

