--
-- Triggers `allocations`
--
DROP TRIGGER IF EXISTS `allocations_within_payment_ins`;
DELIMITER $$
CREATE TRIGGER `allocations_within_payment_ins` BEFORE INSERT ON `allocations` FOR EACH ROW BEGIN
                  DECLARE receipt_cur  BIGINT UNSIGNED;
                  DECLARE receipt_net  DECIMAL(12,2);
                  DECLARE already_used DECIMAL(12,2);
                  DECLARE msg VARCHAR(255);

                  SELECT currency_original_id, net_received INTO receipt_cur, receipt_net
                    FROM payments_in WHERE receipt_code = NEW.receipt_code;

                  IF NEW.currency_id <> receipt_cur THEN
                    SET msg = CONCAT('عملة التخصيص «',
                      (SELECT value FROM lookup_values WHERE id = NEW.currency_id),
                      '» تخالف عملة الإيصال «',
                      (SELECT value FROM lookup_values WHERE id = receipt_cur),
                      '». لا يُطرح مبلغ من مبلغ بعملة أخرى.');
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                  END IF;

                  SELECT COALESCE(SUM(amount), 0) INTO already_used
                    FROM allocations WHERE receipt_code = NEW.receipt_code ;

                  IF already_used + NEW.amount > receipt_net + 0.001 THEN
                    SET msg = CONCAT('التخصيص يتجاوز الدفعة ', NEW.receipt_code,
                      '. المستلم صافياً: ', receipt_net,
                      '، المخصَّص سابقاً: ', already_used,
                      '، المطلوب إضافته: ', NEW.amount, '.');
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                  END IF;
                END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `allocations_within_payment_upd`;
DELIMITER $$
CREATE TRIGGER `allocations_within_payment_upd` BEFORE UPDATE ON `allocations` FOR EACH ROW BEGIN
                  DECLARE receipt_cur  BIGINT UNSIGNED;
                  DECLARE receipt_net  DECIMAL(12,2);
                  DECLARE already_used DECIMAL(12,2);
                  DECLARE msg VARCHAR(255);

                  SELECT currency_original_id, net_received INTO receipt_cur, receipt_net
                    FROM payments_in WHERE receipt_code = NEW.receipt_code;

                  IF NEW.currency_id <> receipt_cur THEN
                    SET msg = CONCAT('عملة التخصيص «',
                      (SELECT value FROM lookup_values WHERE id = NEW.currency_id),
                      '» تخالف عملة الإيصال «',
                      (SELECT value FROM lookup_values WHERE id = receipt_cur),
                      '». لا يُطرح مبلغ من مبلغ بعملة أخرى.');
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                  END IF;

                  SELECT COALESCE(SUM(amount), 0) INTO already_used
                    FROM allocations WHERE receipt_code = NEW.receipt_code AND allocation_id <> NEW.allocation_id;

                  IF already_used + NEW.amount > receipt_net + 0.001 THEN
                    SET msg = CONCAT('التخصيص يتجاوز الدفعة ', NEW.receipt_code,
                      '. المستلم صافياً: ', receipt_net,
                      '، المخصَّص سابقاً: ', already_used,
                      '، المطلوب إضافته: ', NEW.amount, '.');
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                  END IF;
                END
$$
DELIMITER ;

