--
-- Triggers `crypto_payments`
--
DROP TRIGGER IF EXISTS `crypto_payments_frozen_update`;
DELIMITER $$
CREATE TRIGGER `crypto_payments_frozen_update` BEFORE UPDATE ON `crypto_payments` FOR EACH ROW BEGIN
              IF OLD.status = 'confirmed' AND (
                    NEW.status <> OLD.status
                 OR NOT (NEW.txid <=> OLD.txid)
                 OR NOT (NEW.network_code <=> OLD.network_code)
                 OR NOT (NEW.amount_received <=> OLD.amount_received)
                 OR NOT (NEW.requested_amount_usd <=> OLD.requested_amount_usd)
                 OR NOT (NEW.receipt_code <=> OLD.receipt_code)
                 OR NOT (NEW.donation_code <=> OLD.donation_code)
                 OR NEW.is_deleted <> OLD.is_deleted
              ) THEN
                SIGNAL SQLSTATE '45000'
                  SET MESSAGE_TEXT = 'دفعة USDT مؤكَّدة قُيّدت في الدفاتر: لا تُعدَّل، ويُصحَّح الخطأ بقيد عكسي';
              END IF;

              IF OLD.status IN ('rejected', 'expired') AND NEW.status <> OLD.status THEN
                SIGNAL SQLSTATE '45000'
                  SET MESSAGE_TEXT = 'الرفض والانتهاء حالتان نهائيتان: يُنشأ طلب جديد بدل إحيائه';
              END IF;
            END
$$
DELIMITER ;

