--
-- Triggers `sponsorships`
--
DROP TRIGGER IF EXISTS `sponsorships_coverage_guard_ins`;
DELIMITER $$
CREATE TRIGGER `sponsorships_coverage_guard_ins` BEFORE INSERT ON `sponsorships` FOR EACH ROW BEGIN
                  DECLARE existing_total INT;
                  DECLARE child_code VARCHAR(40);
                  DECLARE msg VARCHAR(255);

                  IF (SELECT value FROM lookup_values WHERE id = NEW.state_id)
                     IN ('نشط','متأخر','معرّض للانقطاع','مسودة') THEN

                    SELECT COALESCE(SUM(s.coverage_pct),0) INTO existing_total
                      FROM sponsorships s
                      JOIN lookup_values lv ON lv.id = s.state_id
                     WHERE s.orphan_id = NEW.orphan_id
                       AND lv.value IN ('نشط','متأخر','معرّض للانقطاع','مسودة')
                       AND s.contract_code <> NEW.contract_code;

                    IF existing_total + NEW.coverage_pct > 100 THEN
                      SELECT orphan_code INTO child_code FROM orphans WHERE id = NEW.orphan_id LIMIT 1;
                      SET msg = CONCAT('مجموع نسب التغطية للطفل ', COALESCE(child_code, NEW.orphan_id),
                        ' سيصبح ', existing_total + NEW.coverage_pct,
                        '٪ وهو يتجاوز 100٪. القائم: ', existing_total,
                        '٪، المضاف: ', NEW.coverage_pct, '٪.');
                      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
                    END IF;
                  END IF;
                END
$$
DELIMITER ;
