--
-- Structure for view `v_data_quality`
--
DROP TABLE IF EXISTS `v_data_quality`;

DROP VIEW IF EXISTS `v_data_quality`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_data_quality`  AS SELECT 'سجلات منتهية الصلاحية' AS `issue`, count(0) AS `affected`, 'orphans' AS `src` FROM (`orphans` `o` join `lookup_values` `lv` on((`lv`.`id` = `o`.`file_state_id`))) WHERE ((`o`.`data_valid_until` < curdate()) AND (`lv`.`value` = 'معتمد')) union all select 'أطفال تجاوزوا سن التخريج' AS `أطفال تجاوزوا سن التخريج`,count(0) AS `COUNT(*)`,'orphans' AS `orphans` from (`orphans` `o` join `lookup_values` `lv` on((`lv`.`id` = `o`.`file_state_id`))) where ((`lv`.`value` = 'معتمد') and (`o`.`birth_date` <= (curdate() - interval 18 year))) union all select 'تسليمات بلا تأكيد تجاوزت المهلة' AS `تسليمات بلا تأكيد تجاوزت المهلة`,count(0) AS `COUNT(*)`,'deliveries' AS `deliveries` from `v_unconfirmed_deliveries` where (`v_unconfirmed_deliveries`.`status` = 'معلّق للتحقيق') union all select 'وصي يستلم لأكثر من 5 أطفال' AS `وصي يستلم لأكثر من 5 أطفال`,count(0) AS `COUNT(*)`,'guardians' AS `guardians` from (select `g`.`guardian_code` AS `guardian_code` from (`guardians` `g` join `orphans` `o` on((`o`.`family_code` = `g`.`family_code`))) where (`g`.`is_recipient` = 1) group by `g`.`guardian_code` having (count(0) > 5)) `q` union all select 'نفس رقم الجوال على أكثر من 3 أسر' AS `نفس رقم الجوال على أكثر من 3 أسر`,count(0) AS `COUNT(*)`,'guardians' AS `guardians` from (select `guardians`.`phone_primary` AS `phone_primary` from `guardians` group by `guardians`.`phone_primary` having (count(distinct `guardians`.`family_code`) > 3)) `q2` union all select 'ملفات معتمدة بلا زيارة ميدانية' AS `ملفات معتمدة بلا زيارة ميدانية`,count(0) AS `COUNT(*)`,'orphans' AS `orphans` from (`orphans` `o` join `lookup_values` `lv` on((`lv`.`id` = `o`.`file_state_id`))) where ((`lv`.`value` = 'معتمد') and exists(select 1 from `field_visits` `v` where (`v`.`family_code` = `o`.`family_code`)) is false) union all select 'دفعات محصَّلة غير مخصصة' AS `دفعات محصَّلة غير مخصصة`,count(0) AS `COUNT(*)`,'payments_in' AS `payments_in` from `v_unallocated_payments` where (`v_unallocated_payments`.`remaining` > 0) union all select 'دفعات مخصَّصة بأكثر من المستلم' AS `دفعات مخصَّصة بأكثر من المستلم`,count(0) AS `COUNT(*)`,'payments_in' AS `payments_in` from `v_unallocated_payments` where (`v_unallocated_payments`.`remaining` < 0) union all select 'عملات بلا سعر صرف مثبَّت هذا الشهر' AS `عملات بلا سعر صرف مثبَّت هذا الشهر`,count(0) AS `COUNT(*)`,'fx_rates' AS `fx_rates` from (select `cur`.`currency` AS `currency` from (select `lv`.`value` AS `currency` from (`sponsorships` `s` join `lookup_values` `lv` on((`lv`.`id` = `s`.`currency_id`))) union select `lv`.`value` AS `value` from (`payments_in` `p` join `lookup_values` `lv` on((`lv`.`id` = `p`.`currency_original_id`)))) `cur` where ((`cur`.`currency` <> 'USD') and exists(select 1 from ((`fx_rates` `f` join `lookup_values` `lq` on((`lq`.`id` = `f`.`quote_id`))) join `lookup_values` `lb` on((`lb`.`id` = `f`.`base_id`))) where ((`lq`.`value` = `cur`.`currency`) and (`lb`.`value` = 'USD') and (`f`.`is_provisional` = 0) and (`f`.`month` = date_format(curdate(),'%Y-%m-01')))) is false)) `q4`  ;

