--
-- Structure for view `v_orphan_sponsorship`
--
DROP TABLE IF EXISTS `v_orphan_sponsorship`;

DROP VIEW IF EXISTS `v_orphan_sponsorship`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_orphan_sponsorship`  AS SELECT `o`.`id` AS `orphan_id`, `o`.`orphan_code` AS `orphan_code`, `o`.`full_name` AS `full_name`, `o`.`family_code` AS `family_code`, `lvf`.`value` AS `file_state`, `o`.`need_score` AS `need_score`, `o`.`doc_score` AS `doc_score`, `o`.`nominated_at` AS `nominated_at`, coalesce(sum((case when (`lvs`.`value` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`coverage_pct` else 0 end)),0) AS `covered_pct`, (case when (`lvf`.`value` in ('مُنهى','مرفوض')) then 'خارج البرنامج' when (`lvf`.`value` = 'موقوف مؤقتاً') then 'موقوف' when (`lvf`.`value` <> 'معتمد') then 'قيد المعالجة' when (coalesce(sum((case when (`lvs`.`value` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`coverage_pct` else 0 end)),0) >= 100) then 'مكفول' when (coalesce(sum((case when (`lvs`.`value` in ('نشط','متأخر','معرّض للانقطاع')) then `s`.`coverage_pct` else 0 end)),0) > 0) then 'مكفول جزئياً' when (`o`.`nominated_at` is not null) then 'بانتظار كافل' else 'معتمد' end) AS `sponsorship_state` FROM (((`orphans` `o` join `lookup_values` `lvf` on((`lvf`.`id` = `o`.`file_state_id`))) left join `sponsorships` `s` on((`s`.`orphan_id` = `o`.`id`))) left join `lookup_values` `lvs` on((`lvs`.`id` = `s`.`state_id`))) GROUP BY `o`.`id`, `o`.`orphan_code`, `o`.`full_name`, `o`.`family_code`, `lvf`.`value`, `o`.`need_score`, `o`.`doc_score`, `o`.`nominated_at``nominated_at`  ;

-- --------------------------------------------------------

--
-- Structure for view `v_unallocated_payments`
--
DROP TABLE IF EXISTS `v_unallocated_payments`;

DROP VIEW IF EXISTS `v_unallocated_payments`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_unallocated_payments`  AS SELECT `p`.`receipt_code` AS `receipt_code`, `p`.`sponsor_code` AS `sponsor_code`, `p`.`net_received` AS `net_received`, `lvc`.`value` AS `currency_original`, `p`.`received_at` AS `received_at`, (to_days(curdate()) - to_days(`p`.`received_at`)) AS `days_unallocated`, (`p`.`net_received` - coalesce(sum(`a`.`amount`),0)) AS `remaining`, (case when ((`p`.`net_received` - coalesce(sum(`a`.`amount`),0)) < 0) then 'مخصَّص بأكثر من المستلم' else 'بانتظار التخصيص' end) AS `status` FROM ((`payments_in` `p` join `lookup_values` `lvc` on((`lvc`.`id` = `p`.`currency_original_id`))) left join `allocations` `a` on((`a`.`receipt_code` = `p`.`receipt_code`))) GROUP BY `p`.`receipt_code`, `p`.`sponsor_code`, `p`.`net_received`, `lvc`.`value`, `p`.`received_at` HAVING (`remaining` <> 0)  ;

-- --------------------------------------------------------

--
-- Structure for view `v_unconfirmed_deliveries`
--
DROP TABLE IF EXISTS `v_unconfirmed_deliveries`;

DROP VIEW IF EXISTS `v_unconfirmed_deliveries`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_unconfirmed_deliveries`  AS SELECT `d`.`delivery_code` AS `delivery_code`, `d`.`orphan_id` AS `orphan_id`, `o`.`orphan_code` AS `orphan_code`, `o`.`full_name` AS `full_name`, `d`.`amount_delivered` AS `amount_delivered`, `lvc`.`value` AS `currency`, `d`.`delivered_at` AS `delivered_at`, `d`.`delivered_by` AS `delivered_by`, (to_days(curdate()) - to_days(cast(`d`.`delivered_at` as date))) AS `days_pending`, 10 AS `threshold_days`, (case when ((to_days(curdate()) - to_days(cast(`d`.`delivered_at` as date))) > 10) then 'معلّق للتحقيق' else 'ضمن المهلة' end) AS `status` FROM ((`deliveries` `d` join `orphans` `o` on((`o`.`id` = `d`.`orphan_id`))) join `lookup_values` `lvc` on((`lvc`.`id` = `d`.`currency_id`))) WHERE ((`d`.`confirmed_at` is null) AND (`d`.`failure_reason` is null))  ;

