INSERT INTO `posts` (`id`, `title`, `slug`, `summary`, `content`, `image`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'انطلاق خريطة ابن المخيم', 'welcome', 'كل بكسل رسالة أمل على خريطة غزة.', '<p>يمكنكم حجز بكسل وكتابة رسالة تبقى على الخريطة.</p>', NULL, '2026-09-24 09:56:05', '2026-09-24 09:48:20', '2026-09-24 09:56:05'),
(2, 'قافلة شتاء إلى غزة', 'winter-aid', 'بطانيات وملابس شتوية للعائلات النازحة.', '<p>نوثّق هنا أثر التبرعات على الأرض. حرّر هذا الخبر من لوحة التحكم.</p>', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1400&q=80', '2026-09-21 09:56:05', '2026-09-24 09:56:05', '2026-09-24 09:56:05'),
(3, 'عيادة ميدانية في المخيم', 'clinic', 'أدوية وكشوفات يومية بدعم من بكسلكم.', '<p>يمكن استبدال الصورة والنص من قسم الأخبار في اللوحة.</p>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=1400&q=80', '2026-09-16 09:56:05', '2026-09-24 09:56:05', '2026-09-24 09:56:05');
