INSERT INTO `experience_types` (`id`, `key`, `name`, `emoji`, `icon`, `tagline`, `description`, `base_price`, `currency`, `features`, `max_chars`, `allowed_media`, `max_photos`, `audio_max_ms`, `duration_days`, `duration_label`, `is_featured`, `includes_archive_share`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'moon_spark', 'Spark', '✦', 'bolt', 'One short note, glowing in the rotation.', 'A single text message on the Moon. Nothing extra — a quick spark that lasts a year.', 5, 'USD', '[\"Text only — up to 280 characters\", \"Stays on the Moon for 1 year\", \"Delivered as a shareable link within minutes of payment.\", \"Printable PDF certificate.\"]', 280, '[\"text\"]', 0, NULL, 365, '1 year on the Moon', 0, 0, 1, 1, '2026-08-16 04:10:56', '2026-09-08 06:09:29'),
(2, 'lunar_journey', 'Lunar Journey', '🌌', 'rocket_launch', 'An animated journey through the stars that ends at your message.', 'A scrolling, parallax landing page built around a single message.', 15, 'USD', NULL, 2000, NULL, 0, NULL, NULL, NULL, 0, 0, 2, 0, '2026-08-16 04:10:56', '2026-09-16 05:19:21'),
(3, 'memory_story', 'Memory Story', '📖', 'auto_stories', 'A story in several frames — photos, audio, and text — living on the moon.', 'A multi-part sequence of media told like an album.', 25, 'USD', NULL, 2000, NULL, 0, NULL, NULL, NULL, 0, 0, 3, 0, '2026-08-16 04:10:56', '2026-09-16 05:19:21'),
(4, 'secret_reveal', 'Secret Reveal', '🎁', 'redeem', 'A wrapped message, revealed only at the moment you choose.', 'Locked content that unlocks automatically at a scheduled reveal time.', 20, 'USD', NULL, 2000, NULL, 0, NULL, NULL, NULL, 0, 0, 4, 0, '2026-08-16 04:10:56', '2026-09-16 05:19:21'),
(5, 'time_capsule', 'Time Capsule', '⏳', 'hourglass_top', 'Send it today, so it arrives in the future you choose.', 'Scheduled delivery with a notification sent at the delivery date.', 30, 'USD', NULL, 2000, NULL, 0, NULL, NULL, NULL, 0, 0, 5, 0, '2026-08-16 04:10:56', '2026-09-16 05:19:21'),
(6, 'eternal_beacon', 'Eternal Beacon', '🌟', 'flare', 'The brightest mark on the Moon — impossible to miss from orbit.', 'A single message drawn at the largest size and the fullest glow the Moon can give.', 50, 'USD', '[\"Drawn at the largest of the four spark sizes\", \"Full golden glow — the brightest tier in the rotation\"]', 2000, NULL, 0, NULL, NULL, NULL, 0, 0, 6, 0, '2026-08-17 05:08:52', '2026-09-16 05:19:21'),
(7, 'glow', 'Glow', '🌙', 'image', 'Your words, with a photograph beside them.', 'A text message and one photo, placed together on the Moon for three years.', 29, 'USD', '[\"Text up to 800 characters\", \"One photo\", \"Stays on the Moon for 3 years\", \"Delivered as a shareable link within minutes of payment.\", \"Printable PDF certificate.\"]', 800, '[\"text\", \"photo\"]', 1, NULL, 1095, '3 years on the Moon', 0, 0, 2, 1, '2026-09-08 04:58:28', '2026-09-16 05:19:21'),
(8, 'beacon', 'Beacon', '🔆', 'campaign', 'Text, a photo, or a voice clip — with an optional countdown.', 'Write it, attach a photo, or record your voice. Optionally lock the words until a date you choose; a countdown sits on the Moon until then. A seven-year mark, drawn brighter in the rotation.', 49, 'USD', '[\"Text up to 1,200 characters\", \"Photo or voice clip (up to 30 seconds)\", \"Optional future reveal with a public countdown\", \"Stays on the Moon for 7 years\", \"Delivered as a shareable link within minutes of payment.\", \"Printable PDF certificate.\"]', 1200, '[\"text\", \"photo\", \"audio\"]', 1, 30000, 2555, '7 years on the Moon', 1, 0, 3, 1, '2026-09-08 04:58:28', '2026-09-16 05:19:21'),
(9, 'archive', 'Archive', '🏅', 'lock', 'The sealed record — QR, a timed reveal, and a ten-year stay.', 'Everything in Beacon, plus up to three photos and a shareable archive card with a QR code. Optionally lock the words until a date you choose; a countdown sits on the Moon until then. A ten-year record.', 99, 'USD', '[\"Text up to 2,000 characters\", \"Up to 3 photos and a voice clip (up to 60 seconds)\", \"Shareable link with QR code\", \"Optional future reveal with a public countdown\", \"Stays on the Moon for 10 years\", \"Delivered as a shareable link within minutes of payment.\", \"Printable PDF certificate.\"]', 2000, '[\"text\", \"photo\", \"audio\"]', 3, 60000, 3650, '10 years on the Moon', 0, 1, 4, 1, '2026-09-08 04:58:28', '2026-09-16 05:19:21');
