INSERT INTO `site_events` (`id`, `title`, `subtitle`, `description`, `location`, `url`, `starts_at`, `ends_at`, `status`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(18, 'Write under the Gibbous Moon', 'Live window · 12–14 September 2026', 'The Moon is waxing toward Harvest. A short live window to pin a note while the disc is already bright enough to write by.', 'Night sky worldwide', 'https://www.timeanddate.com/moon/phases/', '2026-09-12 15:00:00', '2026-09-14 05:00:00', NULL, 1, 1, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(19, 'Partial Lunar Eclipse — Sturgeon Moon', 'Moon · 28 August 2026', 'The August full moon — the Sturgeon Moon — passes through Earth’s umbra. At greatest eclipse about 93% of the disc is in shadow, so the Moon looks copper-red from anywhere it is above the horizon in the Americas, Europe, and Africa.', 'Night sky · Americas, Europe, Africa', 'https://www.timeanddate.com/eclipse/lunar/2026-august-28', '2026-08-27 18:00:00', '2026-08-28 03:30:00', NULL, 1, 2, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(20, 'International Day of Peace', 'United Nations · 21 September 2026', 'A UN day of ceasefire and non-violence, observed worldwide. A quiet night to send a message of reconciliation — to someone you love, or to the world at large.', 'Worldwide', 'https://www.un.org/en/observances/international-day-peace', '2026-09-20 21:00:00', '2026-09-21 20:59:00', NULL, 1, 3, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(21, 'September Equinox', 'First day of autumn · 23 September 2026', 'The Sun crosses the celestial equator at 00:06 UTC. Day and night are nearly equal everywhere on Earth: autumn begins in the Northern Hemisphere, spring in the Southern.', 'Worldwide', 'https://earthsky.org/astronomy-essentials/everything-you-need-to-know-september-equinox/', '2026-09-22 21:06:00', '2026-09-22 22:06:00', NULL, 1, 4, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(22, 'Harvest Moon', 'Full moon closest to the equinox · 26 September 2026', 'The Harvest Moon is the full moon nearest the September equinox. For several evenings it rises soon after sunset, flooding the horizon with the extra light that once helped bring in the crop.', 'Night sky worldwide', 'https://www.timeanddate.com/astronomy/moon/harvest.html', '2026-09-26 13:49:00', '2026-09-27 01:00:00', NULL, 1, 5, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(23, 'World Space Week', 'United Nations · 4–10 October 2026', 'The UN week for space science, marked from the launch of Sputnik 1 (4 October 1957) to the Outer Space Treaty (10 October 1967). Observatories, schools, and clubs host public nights under the Moon.', 'Worldwide', 'https://www.worldspaceweek.org/', '2026-10-03 21:00:00', '2026-10-10 20:59:00', NULL, 1, 6, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(24, 'Sweetest Day', 'A day for small kindnesses · 17 October 2026', 'The third Saturday of October in the United States — a quieter counterpart to Valentine’s Day, meant for the people who rarely get the card: a parent, a friend, someone who looked after you.', 'United States · observed worldwide', 'https://nationaltoday.com/sweetest-day/', '2026-10-16 21:00:00', '2026-10-17 20:59:00', NULL, 1, 7, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(25, 'Orionid Meteor Shower', 'Debris from Halley’s Comet · 21–22 October 2026', 'Peak night for the Orionids: typically 10–20 meteors an hour after midnight, radiating from Orion. The waxing Moon will be bright; the darkest hour is between moonset and dawn.', 'Night sky worldwide', 'https://www.amsmeteors.org/meteor-showers/meteor-shower-calendar/', '2026-10-21 19:00:00', '2026-10-22 07:00:00', NULL, 1, 8, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(26, 'Hunter’s Moon', 'October full moon · 25 October 2026', 'The full moon after Harvest Moon. Traditionally named for the hunting season that followed the harvest, it rises large and amber, close to sunset, for a few nights in a row.', 'Night sky worldwide', 'https://www.timeanddate.com/astronomy/moon/full-moon.html', '2026-10-25 00:12:00', '2026-10-25 12:00:00', NULL, 1, 9, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(27, 'Diwali — Festival of Lights', '8 November 2026', 'The Hindu festival of lights, marking the victory of light over darkness. Families light diyas, share sweets, and send blessings home — a night made for a message that stays.', 'India · Nepal · Hindu communities worldwide', 'https://www.timeanddate.com/holidays/india/diwali', '2026-11-07 22:00:00', '2026-11-08 21:59:00', NULL, 1, 10, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(28, 'Singles’ Day', '11 November 2026', 'Born in China as a celebration of being unattached (11.11), now a global day of both self-kindness and shopping. A good night to write something for yourself, or for the person you have not told yet.', 'Worldwide', 'https://en.wikipedia.org/wiki/Singles%27_Day', '2026-11-10 22:00:00', '2026-11-11 21:59:00', NULL, 1, 11, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(29, 'Beaver Moon — Supermoon', 'Closest full moons of the year begin · 24 November 2026', 'November’s Beaver Moon is a supermoon: full moon near perigee, so the disc looks larger and brighter than usual. The first of a close run of three that closes 2026.', 'Night sky worldwide', 'https://www.timeanddate.com/astronomy/moon/super-full-moon.html', '2026-11-24 12:53:00', '2026-11-25 00:00:00', NULL, 1, 12, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(30, 'Thanksgiving', 'United States · 26 November 2026', 'The fourth Thursday of November: a table, a pause, and the people you would thank out loud. Leave the note on the Moon for the ones who will not be in the room.', 'United States', 'https://www.timeanddate.com/holidays/us/thanksgiving-day', '2026-11-25 22:00:00', '2026-11-26 21:59:00', NULL, 1, 13, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(31, 'Geminid Meteor Shower', 'Strongest shower of the year · 13–14 December 2026', 'The Geminids are the most reliable meteor night of the calendar — bright, slow, often coloured, and visible before midnight. In 2026 the Moon is only a thin crescent, so the sky stays dark.', 'Night sky worldwide', 'https://www.amsmeteors.org/meteor-showers/meteor-shower-calendar/', '2026-12-13 19:00:00', '2026-12-14 08:00:00', NULL, 1, 14, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(32, 'Cold Moon — Supermoon', 'Brightest full moon of 2026 · 23 December 2026', 'December’s Cold Moon is the closest supermoon of the year, a day before Christmas Eve. The largest, brightest full moon of 2026 — a winter disc worth stepping outside for.', 'Night sky worldwide', 'https://www.timeanddate.com/astronomy/moon/full-moon.html', '2026-12-22 23:28:00', '2026-12-23 11:00:00', NULL, 1, 15, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(33, 'Christmas', '25 December 2026', 'A night of gathering, memory, and the people who should have received a letter months ago. Pin it under the Cold Moon while it is still hanging over the holiday.', 'Worldwide', 'https://www.timeanddate.com/holidays/common/christmas-day', '2026-12-24 22:00:00', '2026-12-25 21:59:00', NULL, 1, 16, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(34, 'New Year’s Eve', '31 December 2026', 'The last night of the year. A toast, a countdown, and one message you want waiting on the other side of midnight.', 'Worldwide', 'https://www.timeanddate.com/holidays/fun/new-year-eve', '2026-12-31 16:00:00', '2027-01-01 02:00:00', NULL, 1, 17, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(35, 'Quadrantid Meteor Shower', 'Sharp January peak · 3–4 January 2027', 'A brief, intense shower — up to 80 meteors an hour at its narrow peak — radiating from northern skies. In 2027 only a thin waning crescent Moon interferes before dawn.', 'Night sky · best from the Northern Hemisphere', 'https://www.amsmeteors.org/meteor-showers/meteor-shower-calendar/', '2027-01-03 20:00:00', '2027-01-04 08:00:00', NULL, 1, 18, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(36, 'Annular Solar Eclipse', 'Ring of fire · 6 February 2027', 'The Moon passes in front of the Sun but does not cover it completely, leaving a bright ring. The path of annularity crosses South America and West Africa; a partial eclipse is visible over a much wider area. Never look at the Sun without certified filters.', 'Path: South America · West Africa', 'https://www.timeanddate.com/eclipse/solar/2027-february-6', '2027-02-06 11:00:00', '2027-02-06 17:00:00', NULL, 1, 19, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(37, 'Valentine’s Day', '14 February 2027', 'The world’s day for saying it out loud. A spark on the Moon lasts longer than flowers, and it does not mind if you are a little late putting the words together.', 'Worldwide', 'https://www.timeanddate.com/holidays/us/valentine-day', '2027-02-13 22:00:00', '2027-02-14 21:59:00', NULL, 1, 20, '2026-09-13 03:46:23', '2026-09-13 03:46:23'),
(38, 'Penumbral Lunar Eclipse', 'Snow Moon · 20–21 February 2027', 'February’s full Snow Moon crosses Earth’s faint outer shadow. The shading is subtle — a dusky veil rather than a bite out of the disc — but it is visible from anywhere the Moon is up, without equipment.', 'Night sky worldwide', 'https://www.timeanddate.com/eclipse/lunar/2027-february-20', '2027-02-20 19:10:00', '2027-02-20 23:15:00', NULL, 1, 21, '2026-09-13 03:46:23', '2026-09-13 03:46:23');
