(359, 'card.reserved_body', 'card', 'This Moonji is reserved. The message appears here when payment completes.', NULL, '2026-09-14 07:18:05', '2026-09-14 07:18:05'),
(360, 'wizard.reveal_title', 'wizard', 'Reveal later (optional)', NULL, '2026-09-15 05:59:51', '2026-09-15 05:59:51'),
(361, 'wizard.reveal_card_note', 'wizard', 'Optional: lock the message until a future date — countdown on the Moon.', NULL, '2026-09-15 05:59:51', '2026-09-15 05:59:51'),
(362, 'wizard.reveal_hint', 'wizard', 'The spark sits on the Moon now. Text, photo and voice stay sealed until this time, with a countdown in Recent Sparks.', NULL, '2026-09-15 05:59:51', '2026-09-15 05:59:51'),
