(395, 'pkg.glow.f2', 'pkg', 'One photo', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(396, 'pkg.glow.f3', 'pkg', 'Stays on the Moon for 3 years', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(397, 'pkg.beacon.name', 'pkg', 'Beacon', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(398, 'pkg.beacon.tagline', 'pkg', 'Text, a photo, or a voice clip — with an optional countdown.', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(399, 'pkg.beacon.description', 'pkg', 'Write it, attach a photo, or record your voice. Optionally lock the words until a date you choose; a countdown sits on the Moon until then. A seven-year mark, drawn brighter in the rotation.', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
