(403, 'pkg.beacon.f3', 'pkg', 'Optional future reveal with a public countdown', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(404, 'pkg.beacon.f4', 'pkg', 'Stays on the Moon for 7 years', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(405, 'pkg.archive.name', 'pkg', 'Archive', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(406, 'pkg.archive.tagline', 'pkg', 'The sealed record — QR, a timed reveal, and a ten-year stay.', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(407, 'pkg.archive.description', 'pkg', 'Everything in Beacon, plus up to three photos and a shareable archive card with a QR code. Optionally lock the words until a date you choose; a countdown sits on the Moon until then. A ten-year record.', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(408, 'pkg.archive.duration', 'pkg', '10 years on the Moon', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
(409, 'pkg.archive.f1', 'pkg', 'Text up to 2,000 characters', NULL, '2026-09-16 05:44:00', '2026-09-16 05:44:00'),
