(356, 'pricing.included.place.title', 'pricing', 'A fixed place on the Moon', NULL, '2026-09-30 14:44:03', '2026-09-30 14:44:03'),
(357, 'pricing.included.place.body', 'pricing', 'Your order is stamped with coordinates when it is created, so a shared link always lands on that spot.', NULL, '2026-09-30 14:44:03', '2026-09-30 14:44:03'),
