(486, 'pkg.moon_spark.tagline', 'pkg', 'One short note, glowing in the rotation.', NULL, '2026-09-30 14:44:04', '2026-09-30 14:44:04'),
(487, 'pkg.moon_spark.description', 'pkg', 'A single text message on the Moon. Nothing extra — a quick spark that lasts a year.', NULL, '2026-09-30 14:44:04', '2026-09-30 14:44:04'),
