(502, 'pkg.beacon.name', 'pkg', 'Beacon', NULL, '2026-09-30 14:44:04', '2026-09-30 14:44:04'),
(503, 'pkg.beacon.tagline', 'pkg', 'Text, a photo, or a voice clip — with an optional countdown.', NULL, '2026-09-30 14:44:04', '2026-09-30 14:44:04'),
