INSERT INTO `annual_report_sections` (`id`, `year`, `key`, `title`, `body`, `sort`, `is_published`, `written_by`, `published_at`, `created_at`, `updated_at`, `created_by`, `updated_by`, `deleted_at`, `deleted_by`, `is_deleted`, `user_info`) VALUES
(1, 2025, 'foreword', 'كلمة افتتاحية', 'هذا أول تقرير سنوي نصدره بعد إعادة بناء المنصة حول ثلاث حقائق: أن الكفالة عقد لا حقل، وأن المال يمر بست محطات لكل واحدة مسؤول، وأن من يُدخل غير من يعتمد غير من يصرف غير من يدقق. نبدأ التقرير بما لم نُنجزه، لا بما أنجزناه.', 10, 1, 'a27462c7-15d7-405a-8da4-c0a86f7ecbf0', '2026-05-08 16:46:29', '2026-08-08 16:46:29', '2026-08-08 16:46:29', NULL, NULL, NULL, NULL, 0, NULL),
(2, 2025, 'challenges', 'التحديات التي واجهتنا', 'عمولة تسييل النقد كانت أثقل بند علينا: تراوحت بين 15٪ و40٪ حسب الفترة، وهي تُقتطع من كفالة طفل لا من موازنة تشغيل. بدأنا التفاوض الجماعي مع الصرافين وتجريب القسائم الشرائية والمحافظ الإلكترونية كبدائل. والتحدي الثاني هو النزوح: عنوان مسجَّل يصبح خاطئاً خلال أسابيع، ولذلك ألزمنا أنفسنا برقمَي تواصل من شخصين مختلفين وبإعادة تحقق كل ستة أشهر.', 20, 1, 'a27462c7-15d7-405a-8da4-c0a86f7ecbf0', '2026-05-08 16:46:29', '2026-08-08 16:46:29', '2026-08-08 16:46:29', NULL, NULL, NULL, NULL, 0, NULL),
(3, 2025, 'not_achieved', 'ما لم نُنجزه هذا العام', 'لم نصل إلى دير البلح ورفح — لا سجل واحد معتمد فيهما. وهذا لا يعني غياب الأيتام هناك، بل أن التسجيل يصل حيث تصل شبكة معارفنا فقط، أي أن نمونا محكوم بالعلاقات لا بالاحتياج. ولم نبلغ هدف نسبة التغطية 60٪، ولم نُجرِ تدقيقاً خارجياً مستقلاً بعد.', 30, 1, 'a27462c7-15d7-405a-8da4-c0a86f7ecbf0', '2026-05-08 16:46:29', '2026-08-08 16:46:29', '2026-08-08 16:46:29', NULL, NULL, NULL, NULL, 0, NULL),
(4, 2026, 'foreword', 'كلمة افتتاحية', NULL, 10, 0, 'a27462c7-15d7-405a-8da4-c0a86f7ecbf0', NULL, '2026-08-08 16:46:29', '2026-08-08 16:46:29', NULL, NULL, NULL, NULL, 0, NULL);
