INSERT INTO `mediated_messages` (`id`, `contract_code`, `direction_id`, `body`, `state_id`, `reviewed_by`, `reviewed_at`, `review_note`, `body_delivered`, `delivered_at`, `created_at`, `updated_at`, `created_by`, `updated_by`, `deleted_at`, `deleted_by`, `is_deleted`, `user_info`) VALUES
(1, 'KFL-26-00001', 157, 'نشكركم ونشكر من يكفل ابننا. التحق بالمدرسة هذا الفصل وصار يحب الحساب.', 155, '01a01a07-85bb-704c-a411-6c6cab9d6fcf', '2026-08-13 12:38:19', NULL, 'نشكركم ونشكر من يكفل ابننا. التحق بالمدرسة هذا الفصل وصار يحب الحساب.', '2026-08-13 12:38:19', '2026-08-12 12:38:19', '2026-08-19 12:38:19', NULL, NULL, NULL, NULL, 0, NULL),
(2, 'KFL-26-00002', 156, 'أرجو أن تصلوني بوالدة الطفل على الواتساب لأطمئن عليه مباشرة.', 154, '01a01a07-85bb-704c-a411-6c6cab9d6fcf', '2026-08-16 12:38:19', 'طلب تواصل مباشر — لا تُفتح قناة بين الكافل والأسرة (§10.3). أُبلغ الكافل بالبديل: رسالة موسَّطة يمر نصها من هنا.', NULL, NULL, '2026-08-15 12:38:19', '2026-08-19 12:38:19', NULL, NULL, NULL, NULL, 0, NULL),
(3, 'KFL-26-00001', 156, 'بلّغوا الأسرة سلامي، وأسأل الله أن يعينهم. هل يحتاج الطفل شيئاً للمدرسة؟', 152, NULL, NULL, NULL, NULL, NULL, '2026-08-19 12:38:19', '2026-08-19 12:38:19', NULL, NULL, NULL, NULL, 0, NULL);
